mapper.select:
SELECT code, name, normalized_name, region, aliases::text AS aliases, latitude, longitude,
       dataset_version, is_active, created_at
FROM provinces WHERE code = #{code}

SELECT * FROM passport_events
WHERE user_id = #{userId}
AND is_hidden = FALSE
ORDER BY occurred_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT * FROM passport_events
WHERE user_id = #{userId} AND province_code = #{provinceCode}
ORDER BY occurred_at DESC
LIMIT #{limit}
